import { readFileSync } from "fs";

let n = Number(readFileSync(0, "utf8").trim());

// 大きい硬貨から、使えるだけ使う
let coins = 0;
for (const c of [500, 100, 50, 10, 5, 1]) {
  coins += Math.floor(n / c);
  n %= c;
}
console.log(coins);
